export const expDescriptorBody = (withPath: boolean) =>
  `version="0.1.0"
tags={
\t"Gameplay"
\t"Alternative History"
}
name="${EXP_MOD_NAME}"
picture="thumbnail.png"
supported_version="1.*"
dependencies={
\t"Grand Duchy Rising"
}
${withPath ? `path="mod/${EXP_MOD_ID}"\n` : ''}`;

export function buildExperimentalMod(): { files: ModFile[]; launcher: ModFile } {
  const files: ModFile[] = [];
  const t = (path: string, content: string | Uint8Array) => files.push({ path, content });

  t('descriptor.mod', expDescriptorBody(false));
  t('thumbnail.png', makePng(512, 512, [160, 86, 34]));

  // Super event (gui, scripted gui, sound asset, event). The .ogg itself is not generated.
  for (const [path, content] of Object.entries(generateSuperEventFiles(SUPER_EVENT))) t(path, content);

  t('common/bop/GDX_bop.txt', generateBopScript(BOP));
  t('common/ideologies/GDX_ideologies.txt', generateIdeologyScript([IDEOLOGY]));
  t('common/autonomous_states/GDX_autonomy.txt', generateAutonomyScript([AUTONOMY]));
  const faction = generateFactionScript(FACTION);
  t('common/factions/rules/GDX_rules.txt', faction.rulesScript);
  t('common/factions/goals/GDX_goals.txt', faction.goalsScript);
  t('common/timed_activities/GDX_timed_activities.txt', generateTimedActivityScript(TIMED));

  t('common/resources/GDX_resources.txt', generateResourcesScript(RESOURCES));
  t('common/buildings/GDX_buildings.txt', generateBuildingsScript(BUILDINGS));
  t('common/raids/GDX_raids.txt', generateRaidScript(RAID));
  t('common/special_projects/projects/GDX_projects.txt', generateSpecialProjectScript(PROJECT));
  t('common/scripted_effects/GDX_variants.txt', 'GDX_create_variants = {' + String.fromCharCode(10) + generateEquipmentVariantScript(VARIANT) + '}' + String.fromCharCode(10));

  const tracks = [{ song: 'gdx_ducal_theme', assetFile: 'music/gdx_ducal_theme.ogg', chanceFactor: 1, modifiers: [{ factor: 0.5, conditions: { has_war: 'yes' } }] }];
  t('music/GDX_music.txt', generateMusicStationScript('gdx_station', tracks));
  t('music/GDX_music.asset', generateMusicAssetScript(tracks));

  t('interface/GDX_parliament.gui', guiScript());

  // Landless country + flags. The generated state file is skipped so Luxembourg's vanilla history is not overridden.
  const country = scaffoldCountryFiles(COUNTRY);
  for (const f of country.files) {
    if (f.path.startsWith('history/states/')) continue;
    t(f.path, f.content);
  }
  // No common/countries/colors.txt: a mod copy would replace every vanilla country colour.
  for (const flag of batchGenerateFlagTgas(TAG)) t(flag.path, flag.buffer);

  const loc = locEntries();
  for (const lang of ['english', 'german', 'french'] as Hoi4Language[]) {
    t(`localisation/${lang}/GDX_exp_l_${lang}.yml`, formatLocalizationYaml(lang, loc));
  }

  const val = validateModDescriptor(expDescriptorBody(false));
  if (!val.valid) throw new Error(`experimental descriptor invalid: ${val.errors.join(', ')}`);
  return { files, launcher: { path: `${EXP_MOD_ID}.mod`, content: expDescriptorBody(true) } };
}
